-- SEMESTRE COMPLETO DE DEMONSTRAÇÃO (2026/2) — gerado por scripts/gerar_semestre_demo_sql.py a partir de app/demo_semestre.py.
-- ATENÇÃO: APAGA todos os dados (cursos, turmas, instrutores, salas, semestres, aulas, observações...) e carrega a demonstração.
-- MANTÉM: unidades, áreas, turnos e horários oficiais, configurações, perfis e usuários (os de instrutor perdem o vínculo antigo).
-- Requer as atualizações 0003, 0004 e 0005. Cole o arquivo inteiro no SQL Editor do Supabase e clique em Run.
-- Conteúdo: 2 unidades, 11 áreas, 11 cursos, 13 turmas (manhã, tarde e noite), 29 instrutores, 19 salas e laboratórios,
-- 909 aulas geradas pelo gerador de horários, semestre PUBLICADO, aulas até 15/10 marcadas como realizadas,
-- uma substituição, observações de instrutores e as notificações do portal.
-- Logins do portal do instrutor (senha portal@2026): juliana.prates, marcos.vieira, igor.batista, eduardo.salles.

-- 1) Limpeza (igual a limpar_dados_teste.sql)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM unidades WHERE codigo = 'BEIRA-MAR') OR NOT EXISTS (SELECT 1 FROM unidades WHERE codigo = 'PORTO') THEN
    RAISE EXCEPTION 'Unidades oficiais não encontradas: aplique antes as atualizações 0003 e 0004.';
  END IF;
  -- portal do instrutor (atualização 0005): os usuários de instrutor continuam, só perdem o vínculo
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'usuarios' AND column_name = 'instrutor_id') THEN
    EXECUTE 'UPDATE usuarios SET instrutor_id = NULL WHERE instrutor_id IS NOT NULL';
  END IF;
  EXECUTE 'TRUNCATE TABLE
    alocacao_recursos,
    alocacoes,
    ambiente_areas,
    ambientes,
    atividades,
    bloqueios,
    calendario_excecoes,
    calendarios,
    cenarios_planejamento,
    competencias_instrutores,
    cursos,
    deslocamentos_unidades,
    disponibilidade_ambientes,
    disponibilidade_instrutores,
    excecoes_autorizadas,
    execucoes_otimizacao,
    habilitacoes_instrutores,
    horarios_funcionamento,
    importacoes,
    instrutor_areas,
    instrutor_unidades,
    matrizes_curriculares,
    ocorrencias_validacao,
    recursos,
    recursos_ambientes,
    registros_decisao,
    resultados_otimizacao,
    setores,
    simulacoes_capacidade,
    tipos_ambiente,
    turma_uc,
    turmas,
    uc_prerequisitos,
    uc_recursos,
    uc_tipos_ambiente,
    unidades_curriculares,
    validacoes,
    versoes_planejamento'
    || CASE WHEN to_regclass('public.observacoes_instrutor') IS NOT NULL THEN ', observacoes_instrutor' ELSE '' END
    || CASE WHEN to_regclass('public.notificacoes') IS NOT NULL THEN ', notificacoes' ELSE '' END
    || ' RESTART IDENTITY';
  -- instrutores: DELETE (a tabela de usuários, que é mantida, aponta para ela)
  DELETE FROM instrutores;
  PERFORM setval(pg_get_serial_sequence('instrutores', 'id'), 1, false);
  -- escopos de acesso que apontavam para cursos/turmas apagados ou unidades extras
  DELETE FROM permissoes WHERE escopo_tipo IN ('curso', 'turma')
     OR (escopo_tipo = 'unidade' AND escopo_id NOT IN (SELECT id FROM unidades WHERE codigo IN ('BEIRA-MAR', 'PORTO')));
  DELETE FROM periodos_horarios WHERE unidade_id NOT IN (SELECT id FROM unidades WHERE codigo IN ('BEIRA-MAR', 'PORTO'));
  DELETE FROM turnos WHERE unidade_id NOT IN (SELECT id FROM unidades WHERE codigo IN ('BEIRA-MAR', 'PORTO'));
  DELETE FROM areas WHERE unidade_id NOT IN (SELECT id FROM unidades WHERE codigo IN ('BEIRA-MAR', 'PORTO'));
  DELETE FROM unidades WHERE codigo NOT IN ('BEIRA-MAR', 'PORTO');
  DELETE FROM configuracoes WHERE chave = 'worker_status';
END $$;

-- 2) Semestre de demonstração
DO $$
BEGIN
  IF to_regclass('public.notificacoes') IS NULL THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0005.sql (portal do instrutor, notificações e substituição).';
  END IF;
  IF EXISTS (SELECT 1 FROM turmas) OR EXISTS (SELECT 1 FROM instrutores) THEN
    RAISE EXCEPTION 'A limpeza (parte 1) não foi executada: rode o arquivo inteiro.';
  END IF;
  -- tipos_ambiente: 11
  PERFORM setval(pg_get_serial_sequence('tipos_ambiente', 'id'), (SELECT max(id) FROM tipos_ambiente));
  -- calendarios: 2
  PERFORM setval(pg_get_serial_sequence('calendarios', 'id'), (SELECT max(id) FROM calendarios));
  -- ambientes: 19
  PERFORM setval(pg_get_serial_sequence('ambientes', 'id'), (SELECT max(id) FROM ambientes));
  -- calendario_excecoes: 8
  PERFORM setval(pg_get_serial_sequence('calendario_excecoes', 'id'), (SELECT max(id) FROM calendario_excecoes));
  -- cursos: 11
  PERFORM setval(pg_get_serial_sequence('cursos', 'id'), (SELECT max(id) FROM cursos));
  -- instrutores: 29
  PERFORM setval(pg_get_serial_sequence('instrutores', 'id'), (SELECT max(id) FROM instrutores));
  -- ambiente_areas: 12
  -- disponibilidade_instrutores: 235
  PERFORM setval(pg_get_serial_sequence('disponibilidade_instrutores', 'id'), (SELECT max(id) FROM disponibilidade_instrutores));
  -- habilitacoes_instrutores: 9
  PERFORM setval(pg_get_serial_sequence('habilitacoes_instrutores', 'id'), (SELECT max(id) FROM habilitacoes_instrutores));
  -- instrutor_areas: 16
  -- matrizes_curriculares: 11
  PERFORM setval(pg_get_serial_sequence('matrizes_curriculares', 'id'), (SELECT max(id) FROM matrizes_curriculares));
  -- notificacoes: 27
  PERFORM setval(pg_get_serial_sequence('notificacoes', 'id'), (SELECT max(id) FROM notificacoes));
  -- cenarios_planejamento: 1
  PERFORM setval(pg_get_serial_sequence('cenarios_planejamento', 'id'), (SELECT max(id) FROM cenarios_planejamento));
  -- unidades_curriculares: 39
  PERFORM setval(pg_get_serial_sequence('unidades_curriculares', 'id'), (SELECT max(id) FROM unidades_curriculares));
  -- competencias_instrutores: 78
  PERFORM setval(pg_get_serial_sequence('competencias_instrutores', 'id'), (SELECT max(id) FROM competencias_instrutores));
  -- execucoes_otimizacao: 1
  PERFORM setval(pg_get_serial_sequence('execucoes_otimizacao', 'id'), (SELECT max(id) FROM execucoes_otimizacao));
  -- registros_decisao: 2
  PERFORM setval(pg_get_serial_sequence('registros_decisao', 'id'), (SELECT max(id) FROM registros_decisao));
  -- uc_tipos_ambiente: 45
  -- validacoes: 4
  PERFORM setval(pg_get_serial_sequence('validacoes', 'id'), (SELECT max(id) FROM validacoes));
  -- resultados_otimizacao: 6
  PERFORM setval(pg_get_serial_sequence('resultados_otimizacao', 'id'), (SELECT max(id) FROM resultados_otimizacao));
  -- turmas: 13
  PERFORM setval(pg_get_serial_sequence('turmas', 'id'), (SELECT max(id) FROM turmas));
  -- turma_uc: 46
  PERFORM setval(pg_get_serial_sequence('turma_uc', 'id'), (SELECT max(id) FROM turma_uc));
  -- atividades: 63
  PERFORM setval(pg_get_serial_sequence('atividades', 'id'), (SELECT max(id) FROM atividades));
  -- observacoes_instrutor: 3
  PERFORM setval(pg_get_serial_sequence('observacoes_instrutor', 'id'), (SELECT max(id) FROM observacoes_instrutor));
  -- alocacoes: 909
  PERFORM setval(pg_get_serial_sequence('alocacoes', 'id'), (SELECT max(id) FROM alocacoes));
END $$;

-- 3) Acesso ao portal de alguns instrutores (a senha fica só como hash bcrypt)
SELECT i.nome, 'juliana.prates', '$2b$12$kkjm7YMZctXpzKsSGl3hae06qwkrQv/S.V/dAEzbRt5FsRJjFEviW', 'instrutor', false, true, i.id FROM instrutores i WHERE i.matricula = 'BM-1002'
ON CONFLICT (email) DO UPDATE SET instrutor_id = EXCLUDED.instrutor_id, ativo = true, senha_hash = EXCLUDED.senha_hash WHERE usuarios.perfil = 'instrutor';
SELECT i.nome, 'marcos.vieira', '$2b$12$5tJbxgnqKSDcRcD1UGl/lefmLSiPdv19SHMosCkJlSK6NYCf6Prky', 'instrutor', false, true, i.id FROM instrutores i WHERE i.matricula = 'BM-1001'
ON CONFLICT (email) DO UPDATE SET instrutor_id = EXCLUDED.instrutor_id, ativo = true, senha_hash = EXCLUDED.senha_hash WHERE usuarios.perfil = 'instrutor';
SELECT i.nome, 'igor.batista', '$2b$12$peSP.1/6FLQ2edZQ/dTBLOcG30AD5x36J5vJXStQOnPrcwpRQpUEy', 'instrutor', false, true, i.id FROM instrutores i WHERE i.matricula = 'PT-2006'
ON CONFLICT (email) DO UPDATE SET instrutor_id = EXCLUDED.instrutor_id, ativo = true, senha_hash = EXCLUDED.senha_hash WHERE usuarios.perfil = 'instrutor';
SELECT i.nome, 'eduardo.salles', '$2b$12$pixnnhNBBGkkwjT8UwUZaOZ4wgA7/04VY2K36QW3fB.IFHiBjtnFy', 'instrutor', false, true, i.id FROM instrutores i WHERE i.matricula = 'PT-2004'
ON CONFLICT (email) DO UPDATE SET instrutor_id = EXCLUDED.instrutor_id, ativo = true, senha_hash = EXCLUDED.senha_hash WHERE usuarios.perfil = 'instrutor';

-- 4) Conferência
SELECT (SELECT count(*) FROM cursos) AS cursos, (SELECT count(*) FROM turmas) AS turmas, (SELECT count(*) FROM instrutores) AS instrutores,
       (SELECT count(*) FROM ambientes) AS salas, (SELECT count(*) FROM alocacoes) AS aulas,
       (SELECT estado FROM cenarios_planejamento ORDER BY id LIMIT 1) AS semestre,
       (SELECT count(*) FROM usuarios WHERE perfil = 'instrutor' AND instrutor_id IS NOT NULL) AS logins_portal;
